const envelope = $input.first().json;
const raw = envelope.body ?? envelope;
const scenario = ['continuity', 'adaptation'].includes(raw.scenario) ? raw.scenario : 'continuity';
const proposal = raw.proposal && typeof raw.proposal === 'object' ? raw.proposal : {};
const action = proposal.proposedAction && typeof proposal.proposedAction === 'object' ? proposal.proposedAction : {};
const scorecard = Array.isArray(action.scorecard) ? action.scorecard.slice(0, 5).map(item => ({ professionalId: String(item.professionalId ?? '').slice(0, 40), score: Number(item.score ?? 0), reasons: Array.isArray(item.reasons) ? item.reasons.slice(0, 4).map(reason => String(reason).slice(0, 100)) : [] })) : [];
const selectedCandidateName = String(raw.selectedCandidateName ?? action.selectedCandidate ?? 'the recommended option').slice(0, 80);
const sessionsProtected = Array.isArray(action.sessionUpdates) ? action.sessionUpdates.length : 0;
const deterministicExplanation = String(proposal.explanation ?? 'The deterministic policy created a proposal for human review.').slice(0, 800);
const safeContext = { scenario, selectedCandidateName, sessionsProtected, scorecard, deterministicExplanation, businessRules: Array.isArray(proposal.businessRules) ? proposal.businessRules.slice(0, 6).map(rule => String(rule).slice(0, 100)) : [] };
const prompt = `You are the AI explanation layer of ActiveFlow, an operations automation portfolio demo. The operational decision has already been made by deterministic rules. Never change the decision, invent data, or claim that records were updated. Explain the result to a recruiter in clear business English. Return valid JSON only with these keys: executiveSummary (max 45 words), whyItIsSafe (max 35 words), recruiterTakeaway (max 30 words). Context: ${JSON.stringify(safeContext)}`;
const fallback = { executiveSummary: deterministicExplanation, whyItIsSafe: 'The proposal is version-checked and blocked until a human approves it.', recruiterTakeaway: 'ActiveFlow combines explainable automation, safe orchestration and human control.' };
return [{ json: { scenario, prompt, fallback } }];

const response = $input.first().json;
const source = $('Build Safe Explanation Prompt').first().json;
let explanation = source.fallback;
let aiAvailable = false;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) throw new Error('No Gemini content');
  const parsed = JSON.parse(String(text).replace(/^```json\s*|```$/g, '').trim());
  if (!parsed.executiveSummary || !parsed.whyItIsSafe || !parsed.recruiterTakeaway) throw new Error('Incomplete Gemini response');
  explanation = { executiveSummary: String(parsed.executiveSummary).slice(0, 500), whyItIsSafe: String(parsed.whyItIsSafe).slice(0, 400), recruiterTakeaway: String(parsed.recruiterTakeaway).slice(0, 350) };
  aiAvailable = true;
} catch {}
return [{ json: { ok: true, aiAvailable, model: aiAvailable ? 'gemini-flash-lite-latest' : 'deterministic-fallback', explanation, guardrails: ['AI explains but does not decide', 'no credentials or personal data in prompts', 'human approval remains mandatory', 'fallback preserves demo availability'] } }];
